CREATE TABLE users(user_id TEXT PRIMARY KEY, name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE);
CREATE TABLE homes(home_id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE home_members(home_id TEXT REFERENCES homes, user_id TEXT REFERENCES users, role TEXT NOT NULL CHECK(role IN ('Owner','Member','Installer')), PRIMARY KEY(home_id,user_id));
CREATE TABLE rooms(room_id TEXT PRIMARY KEY, home_id TEXT NOT NULL REFERENCES homes, name TEXT NOT NULL, UNIQUE(home_id,name));
CREATE TABLE factory_devices(factory_id TEXT PRIMARY KEY, product_type TEXT NOT NULL CHECK(product_type IN ('SUB_BOX','ACTION_BOX')), model TEXT NOT NULL, secret BLOB NOT NULL, setup_hash TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE registered_nodes(node_id INTEGER PRIMARY KEY AUTOINCREMENT, factory_id TEXT NOT NULL UNIQUE REFERENCES factory_devices, home_id TEXT NOT NULL REFERENCES homes, registration TEXT NOT NULL CHECK(registration IN ('PAIRING','REGISTERED','TRANSFER_PENDING','REVOKED')), connectivity TEXT NOT NULL DEFAULT 'OFFLINE', config_rev INTEGER NOT NULL DEFAULT 1, reported_rev INTEGER NOT NULL DEFAULT 0, boot_id TEXT, last_seen REAL, firmware TEXT NOT NULL DEFAULT 'unknown');
CREATE TABLE node_assignments(assignment_id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES registered_nodes, room_id TEXT NOT NULL REFERENCES rooms, parent_id INTEGER REFERENCES registered_nodes, primary_subbox INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1, CHECK((primary_subbox=1 AND parent_id IS NULL) OR (primary_subbox=0 AND parent_id IS NOT NULL)));
CREATE UNIQUE INDEX one_assignment ON node_assignments(node_id) WHERE active=1;
CREATE UNIQUE INDEX one_primary ON node_assignments(room_id) WHERE active=1 AND primary_subbox=1;
CREATE TABLE node_credentials(node_id INTEGER PRIMARY KEY REFERENCES registered_nodes, key_cipher BLOB NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE pairing_claims(claim_id TEXT PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES registered_nodes, factory_id TEXT NOT NULL REFERENCES factory_devices, user_id TEXT NOT NULL REFERENCES users, room_id TEXT NOT NULL REFERENCES rooms, parent_id INTEGER, nonce TEXT NOT NULL, expires REAL NOT NULL, status TEXT NOT NULL DEFAULT 'PAIRING');
CREATE UNIQUE INDEX one_pending_claim ON pairing_claims(factory_id) WHERE status='PAIRING';
CREATE TABLE session_challenges(node_id INTEGER PRIMARY KEY REFERENCES registered_nodes, nonce TEXT NOT NULL, boot_id TEXT NOT NULL, expires REAL NOT NULL);
CREATE TABLE admitted_boots(node_id INTEGER NOT NULL REFERENCES registered_nodes, boot_id TEXT NOT NULL, PRIMARY KEY(node_id,boot_id));
CREATE TABLE channels(channel_id TEXT PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES registered_nodes, number INTEGER NOT NULL CHECK(number BETWEEN 1 AND 3), command_generation INTEGER NOT NULL DEFAULT 0, UNIQUE(node_id,number));
CREATE TABLE devices(device_id TEXT PRIMARY KEY, home_id TEXT NOT NULL REFERENCES homes, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('light','fan','outlet','other')));
CREATE TABLE device_bindings(binding_id INTEGER PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices, channel_id TEXT NOT NULL REFERENCES channels, active INTEGER NOT NULL DEFAULT 1, created REAL NOT NULL);
CREATE UNIQUE INDEX channel_binding ON device_bindings(channel_id) WHERE active=1;
CREATE UNIQUE INDEX device_binding ON device_bindings(device_id) WHERE active=1;
CREATE TABLE channel_states(channel_id TEXT PRIMARY KEY REFERENCES channels, relay_state INTEGER CHECK(relay_state IN (0,1)), current_rms_a REAL, ct_valid INTEGER NOT NULL DEFAULT 0, fault_flags INTEGER NOT NULL DEFAULT 0, boot_id TEXT, state_seq INTEGER NOT NULL DEFAULT 0, config_rev INTEGER NOT NULL DEFAULT 0, reported_at REAL);
CREATE TABLE state_events(event_id INTEGER PRIMARY KEY AUTOINCREMENT, home_id TEXT NOT NULL REFERENCES homes, kind TEXT NOT NULL, data TEXT NOT NULL, created REAL NOT NULL);
CREATE INDEX events_home ON state_events(home_id,event_id);
CREATE TABLE room_state_snapshots(room_id TEXT PRIMARY KEY REFERENCES rooms, config_rev INTEGER NOT NULL, snapshot TEXT NOT NULL, updated REAL NOT NULL);
CREATE TABLE config_revisions(node_id INTEGER NOT NULL REFERENCES registered_nodes, revision INTEGER NOT NULL, config TEXT NOT NULL, created REAL NOT NULL, PRIMARY KEY(node_id,revision));
CREATE TABLE commands(command_id TEXT PRIMARY KEY, home_id TEXT NOT NULL REFERENCES homes, user_id TEXT NOT NULL REFERENCES users, idempotency_key TEXT NOT NULL, device_id TEXT NOT NULL REFERENCES devices, channel_id TEXT NOT NULL REFERENCES channels, node_id INTEGER NOT NULL REFERENCES registered_nodes, parent_id INTEGER NOT NULL REFERENCES registered_nodes, boot_id TEXT NOT NULL, config_rev INTEGER NOT NULL, desired INTEGER NOT NULL CHECK(desired IN (0,1)), generation INTEGER NOT NULL, status TEXT NOT NULL, created REAL NOT NULL, expires REAL NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_try REAL NOT NULL, reason TEXT, UNIQUE(user_id,idempotency_key));
CREATE TABLE firmware_artifacts(artifact_id TEXT PRIMARY KEY, model TEXT NOT NULL, version TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT NOT NULL UNIQUE, manifest TEXT NOT NULL, signature TEXT NOT NULL, path TEXT NOT NULL, created REAL NOT NULL);
CREATE TABLE ota_jobs(job_id TEXT PRIMARY KEY, home_id TEXT NOT NULL REFERENCES homes, artifact_id TEXT NOT NULL REFERENCES firmware_artifacts, created REAL NOT NULL, user_id TEXT NOT NULL REFERENCES users);
CREATE TABLE ota_targets(job_id TEXT NOT NULL REFERENCES ota_jobs, node_id INTEGER NOT NULL REFERENCES registered_nodes, status TEXT NOT NULL, offset INTEGER NOT NULL DEFAULT 0, old_boot TEXT, reason TEXT, updated REAL NOT NULL, PRIMARY KEY(job_id,node_id));
CREATE UNIQUE INDEX one_active_ota ON ota_targets(node_id) WHERE status IN ('QUEUED','TRANSFERRING','VERIFYING','REBOOTING','HEALTH_CHECK');
CREATE TABLE audit_logs(audit_id INTEGER PRIMARY KEY, home_id TEXT REFERENCES homes, user_id TEXT REFERENCES users, action TEXT NOT NULL, target TEXT NOT NULL, created REAL NOT NULL);
